1	export type QuoteResult = { premium: number };
2	
3	export type ScenarioResults = { results: QuoteResult[] };
4	
5	const PROCESSING_FEE = 5;
6	
7	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
8	
9	const CURSE_SURCHARGE_RATE = 0.5;
10	
11	const ITEM_BASE_PREMIUM: Record<string, number> = {
12	  sword: 100,
13	  amulet: 60,
14	  staff: 80,
15	  potion: 40,
16	  rune: 25,
17	  moonstone: 25,
18	};
19	
20	type Item = { type: string; cursed?: boolean };
21	
22	type Step = { op: string; items: Item[] };
23	
24	type Scenario = { customer: { yearsWithMHPCO: number }; steps: Step[] };
25	
26	const BLOCK_SIZE = 3;
27	
28	// A block is exactly BLOCK_SIZE components of the same type, priced as a unit.
29	// Exactly: 4 runes are not a block (4 x 25), and 2 runes + 1 moonstone is not
30	// a block either — "alike" means the same type, not the same family.
31	const BLOCK_BASE_PREMIUM = 60;
32	
33	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
34	
35	const countByType = (items: Item[]): Map<string, number> =>
36	  items.reduce(
37	    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
38	    new Map<string, number>(),
39	  );
40	
41	const isBlock = (type: string, count: number): boolean =>
42	  COMPONENT_TYPES.has(type) && count === BLOCK_SIZE;
43	
44	const groupBasePremium = (type: string, count: number): number =>
45	  isBlock(type, count) ? BLOCK_BASE_PREMIUM : count * ITEM_BASE_PREMIUM[type];
46	
47	const sum = (numbers: number[]): number =>
48	  numbers.reduce((total, value) => total + value, 0);
49	
50	const policyBasePremium = (items: Item[]): number =>
51	  sum(
52	    [...countByType(items)].map(([type, count]) =>
53	      groupBasePremium(type, count),
54	    ),
55	  );
56	
57	// Item-specific modifiers apply to the affected item's own base premium, not to
58	// the policy total.
59	const itemModifierSurcharges = (items: Item[]): number =>
60	  sum(
61	    items.map((item) =>
62	      item.cursed ? ITEM_BASE_PREMIUM[item.type] * CURSE_SURCHARGE_RATE : 0,
63	    ),
64	  );
65	
66	const quoteStep = (step: Step): QuoteResult => {
67	  const basePremium =
68	    policyBasePremium(step.items) + itemModifierSurcharges(step.items);
69	  // Deliberately additive, not `base * (1 + rate)`: the latter is the same in
70	  // exact arithmetic but not in binary floating point (100 * 1.1 is
71	  // 110.00000000000001), and Math.ceil turns that 1e-14 into a whole gold piece.
72	  const afterPercentageModifiers =
73	    basePremium + basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
74	
75	  // The fee is added after every percentage modifier, and only the final
76	  // premium is rounded — intermediates stay fractional.
77	  return { premium: Math.ceil(afterPercentageModifiers + PROCESSING_FEE) };
78	};
79	
80	export const runScenario = (scenario: Scenario): ScenarioResults => ({
81	  results: scenario.steps.map(quoteStep),
82	});
